from PIL import Image
im = Image.open('small-separated.png').convert('RGBA')
# silhouette mask
mask = Image.new('RGBA',(16,16),(0,0,0,0))
for y in range(16):
    for x in range(16):
        if im.getpixel((x,y))[3]:
            mask.putpixel((x,y),(0,0,0,255))
def bgimg(kind):
    b=Image.new('RGBA',(16,16))
    for y in range(16):
        for x in range(16):
            if kind=='light': c=(236,236,232,255)
            elif kind=='dark': c=(24,24,28,255)
            else: c=(90,120,70,255) if ((x//2+y//3)%2==0) else (140,110,60,255)
            b.putpixel((x,y),c)
    return b
cells=[]
for kind in ['light','dark','busy']:
    cells.append(Image.alpha_composite(bgimg(kind), im))
    cells.append(Image.alpha_composite(bgimg(kind), mask))
sheet=Image.new('RGBA',(16*6+5*2,16),(255,0,255,255))
for i,c in enumerate(cells): sheet.paste(c,(i*18,0))
sheet.resize((sheet.width*12, sheet.height*12), Image.NEAREST).save('view-contact-sheet.png')
# native-scale row too
sheet.save('view-contact-native.png')
print('cells: colored/mask on light, dark, busy')
